INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 27, 'theory', 'Quiz: functools and operator');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 0, 'What will reduce(operator.add, []) give without an initial value?', '["0", "None", "TypeError: an empty iterable with no initial value", "[]"]', 2, 'The initial value guards against an empty collection: with it, reduce would return it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 1, 'What does partial(int, base=2) do?', '["Calls int right away", "Returns a function with base=2 already fixed", "Converts a number to binary notation", "Nothing"]', 1, 'partial fixes some of the arguments and returns a new function for the rest.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 2, 'Which condition is required for the arguments of a function under @lru_cache?', '["They must be numbers", "They must be hashable (not lists)", "There must be no more than two of them", "They must be strings"]', 1, 'The cache stores the arguments in a dictionary, so a list can''t be passed: unhashable type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 3, 'What must you define in a class with @total_ordering?', '["All six comparison methods", "__eq__ and one ordering operator, for example __lt__", "Only __str__", "Only __hash__"]', 1, 'The decorator builds the other comparisons by itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 4, 'What will itemgetter(''a'', ''b'')(d) return?', '["A single value d[''a'']", "A tuple (d[''a''], d[''b''])", "A dictionary", "A list of keys"]', 1, 'Several keys give a tuple of values, which is handy for sorting by several fields.');
